public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    int count = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@') {
                count++;
                // Use BFS to mark all connected oil deposits
                queueBFS(grid, i, j, rows, cols);
            }
        }
    }

    return count;
}

private static void queueBFS(char[][] grid, int row, int col, int rows, int cols) {
    java.util.Queue<int[]> queue = new java.util.LinkedList<>();
    queue.offer(new int[]{row, col});
    grid[row][col] = '*'; // Mark as visited

    while (!queue.isEmpty()) {
        int[] curr = queue.poll();
        int r = curr[0];
        int c = curr[1];

        // Check all 8 directions
        int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
        int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

        for (int k = 0; k < 8; k++) {
            int nr = r + dr[k];
            int nc = c + dc[k];

            if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '@') {
                grid[nr][nc] = '*';
                queue.offer(new int[]{nr, nc});
            }
        }
    }
}
