public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0] == null || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    int count = 0;
    boolean[][] visited = new boolean[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                dfs(grid, visited, i, j, rows, cols);
            }
        }
    }
    return count;
}

private static void dfs(char[][] grid, boolean[][] visited, int i, int j, int rows, int cols) {
    if (i < 0 || i >= rows || j < 0 || j >= cols || visited[i][j] || grid[i][j] != '@') {
        return;
    }
    visited[i][j] = true;

    // Check all 8 directions
    int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int k = 0; k < 8; k++) {
        int ni = i + dx[k];
        int nj = j + dy[k];
        if (ni >= 0 && ni < rows && nj >= 0 && nj < cols && !visited[ni][nj] && grid[ni][nj] == '@') {
            dfs(grid, visited, ni, nj, rows, cols);
        }
    }
}
