    int count = 0;
    boolean[][] visited = new boolean[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                dfs(grid, i, j, visited, rows, cols);
            }
        }
    }

    return count;
}

private static void dfs(char[][] grid, int row, int col, boolean[][] visited, int rows, int cols) {
    if (row < 0 || row >= rows || col < 0 || col >= cols) {
        return;
    }
    if (visited[row][col] || grid[row][col] != '@') {
        return;
    }

    visited[row][col] = true;

    // 8 directions
    int[] dr = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dc = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int k = 0; k < 8; k++) {
        int nr = row + dr[k];
        int nc = col + dc[k];
        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && !visited[nr][nc] && grid[nr][nc] == '@') {
            dfs(grid, nr, nc, visited, rows, cols);
        }
    }
}
