public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Use BFS to check if we can reach the end from start
    // Nodes are represented as (x, y) pairs
    // We'll use a queue for BFS and a visited set to avoid cycles

    java.util.Queue<int[]> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    // Add start to queue and mark as visited
    queue.offer(start);
    visited.add(start[0] + "," + start[1]);

    while (!queue.isEmpty()) {
        int[] current = queue.poll();

        // Check if we reached the destination
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Explore all paths that start from current node
        for (int[] path : paths) {
            int x1 = path[0];
            int y1 = path[1];
            int x2 = path[2];
            int y2 = path[3];

            // Check if current node matches either endpoint of the path
            boolean matchesFirst = (current[0] == x1 && current[1] == y1);
            boolean matchesSecond = (current[0] == x2 && current[1] == y2);

            if (matchesFirst) {
                // The neighbor is (x2, y2)
                int[] neighbor = new int[]{x2, y2};
                String key = neighbor[0] + "," + neighbor[1];
                if (!visited.contains(key)) {
                    visited.add(key);
                    queue.offer(neighbor);
                }
            } else if (matchesSecond) {
                // The neighbor is (x1, y1)
                int[] neighbor = new int[]{x1, y1};
                String key = neighbor[0] + "," + neighbor[1];
                if (!visited.contains(key)) {
                    visited.add(key);
                    queue.offer(neighbor);
                }
            }
        }
    }

    return "cannot be travelled";
}

