public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null) return "cannot be travelled";
    if (start.length != 2 || end.length != 2) return "cannot be travelled";
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx == ex && sy == ey) return "can be travelled";

    // Build adjacency list
    Map<Integer, List<Integer>> adj = new HashMap<>();
    if (paths != null) {
        for (int[] p : paths) {
            if (p.length >= 4) {
                int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
                int node1 = x1 * n + y1;
                int node2 = x2 * n + y2;
                adj.computeIfAbsent(node1, k -> new ArrayList<>()).add(node2);
                adj.computeIfAbsent(node2, k -> new ArrayList<>()).add(node1);
            }
        }
    }

    // BFS
    int startNode = sx * n + sy;
    int endNode = ex * n + ey;
    Queue<Integer> queue = new LinkedList<>();
    Set<Integer> visited = new HashSet<>();
    queue.offer(startNode);
    visited.add(startNode);

    while (!queue.isEmpty()) {
        int curr = queue.poll();
        if (curr == endNode) {
