public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    if (start[0] == end[0] && start[1] == end[1]) {
        return "can be travelled";
    }

    // Build adjacency list
    List<List<int[]>> adjacency = new ArrayList<>();
    for (int i = 0; i < n * n; i++) {
        adjacency.add(new ArrayList<>());
    }

    // Helper to convert (x, y) to index
    java.util.function.BiFunction<Integer, Integer, Integer> toIndex = (x, y) -> x * n + y;
    java.util.function.IntFunction<int[]> fromIndex = idx -> new int[]{idx / n, idx % n};

    for (int[] path : paths) {
        if (path.length != 4) continue;
        int x1 = path[0], y1 = path[1], x2 = path[2], y2 = path[3];
        if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
            continue;
        }
        int idx1 = toIndex.apply(x1, y1);
        int idx2 = toIndex.apply(x2, y2);
        adjacency.get(idx1).add(new int[]{x2, y2});
        adjacency.get(idx2).add(new int[]{x1, y1});
    }

    // BFS
    int startIdx = toIndex.apply(start[0], start[1]);
    int endIdx = toIndex.apply(end[0], end[1]);

    boolean[] visited = new boolean[n * n];
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);
    visited[startIdx] = true;

    while (!queue.isEmpty()) {
        int[] curr = queue.poll();
        int currIdx = toIndex.apply(curr[0], curr[1]);
        if (currIdx == endIdx) {
            return "can be travelled";
        }
        for (int[] neighbor : adjacency.get(currIdx)) {
            int neighborIdx = toIndex.apply(neighbor[0], neighbor[1]);
            if (!visited[neighborIdx]) {
                visited[neighborIdx] = true;
                queue.offer(neighbor);
            }
        }
    }

    return "cannot be travelled";
}
