            if (c == d) {
                commonCount++;
            }
        }
    }
    int sumLengths = word1.length() + word2.length();
    if (commonCount == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }
    int g = gcd(commonCount, sumLengths);
    int numerator = commonCount / g;
    int denominator = sumLengths / g;
    if (denominator == 1) {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator;
    } else {
        return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
    }
}

