public double trimMean(int[] arr) {
    int n = arr.length;
    if (n == 0) return 0.0;

    // Sort the array
    java.util.Arrays.sort(arr);

    // Calculate the number of elements to remove from each end
    int removeCount = n / 20; // 5% of n

    // Sum the remaining elements
    double sum = 0.0;
    int start = removeCount;
    int end = n - removeCount;

    for (int i = start; i < end; i++) {
        sum += arr[i];
    }

    int remainingCount = end - start;
    return sum / remainingCount;
}
