public String sortString(String s) {
    int[] count = new int[26];
    for (char c : s.toCharArray()) {
        count[c - 'a']++;
    }

    StringBuilder result = new StringBuilder();
    int total = s.length();
    int placed = 0;

    while (placed < total) {
        // Ascending pass
        for (int i = 0; i < 26 && placed < total; i++) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                placed++;
            }
        }

        // Descending pass
        for (int i = 25; i >= 0 && placed < total; i--) {
            if (count[i] > 0) {
                result.append((char) ('a' + i));
                count[i]--;
                placed++;
            }
        }
    }

    return result.toString();
}
