    int sum = 0;
    for (int num : nums) sum += num;
    // We need to find a subset of size k (1 <= k <= n-1) such that
    // sum_of_subset / k == sum / n
    // which means sum_of_subset * n == sum * k
    // Also, sum must be divisible by n in a fractionally sense, but we can avoid floating point
    // by checking: for some k, exists subset of size k with sum = sum * k / n, which requires sum*k % n == 0.

    // Optimization: only consider k from 1 to n/2 (by symmetry, since if there's a subset of size k with the average, there's also one of size n-k)
    // Also, we can sort and use DP with bitset for possible sums for each subset size.

    // First, check if any k makes sum*k divisible by n
    List<Integer> validKs = new java.util.ArrayList<>();
    for (int k = 1; k <= n / 2; k++) {
        if (sum * k % n == 0) {
            validKs.add(k);
        }
    }
    if (validKs.isEmpty()) {
        // Also check k = n/2 + 1 ... n-1? By symmetry, if a subset of size k works, the complement of size n-k also works.
        // So checking k from 1 to n/2 is sufficient.
        return false;
    }

    // Use DP: dp[k] is a BitSet of possible sums for subsets of size k
    // Since n can be up to, say, 100, and values can be large, but let's assume reasonable bounds.
    // Actually worst case sum could be large. Let's use a different approach.
    // Alternative: recursively enumerate subsets using DFS with pruning.

    // Given n could be up to maybe 50, let's use a smarter DFS.

    // Sort the array to help with pruning
    java.util.Arrays.sort(nums);

    // We'll try to find a subset of size k (for k in validKs) with the target sum.
    // targetSum for size k = sum * k / n

    for (int k : validKs) {
        long targetSum = (long) sum * k / n;
        if (dfs(nums, 0, k, targetSum, 0L)) {
            return true;
        }
    }

    return false;
}

private boolean dfs(int[] nums, int index, int targetSize, long targetSum, long currentSum) {
    int n = nums.length;
    if (currentSum > targetSum) {
        return false;
    }
    if (n - index < targetSize) {
        return false;
    }
    if (targetSize == 0) {
        return currentSum == targetSum;
    }
    if (index == n) {
        return false;
    }

    // Pruning: the maximum possible sum we can add from remaining elements
    // If even taking the largest (targetSize) elements from index to n-1 can't reach targetSum, return false
    // But since array is sorted ascending, the largest elements are at the end.

    // Let's compute the maximum possible sum we can get from the last 'targetSize' elements starting from index
    // Actually, the maximum sum we can add is the sum of the last 'targetSize' elements from index to n-1.
    // Since sorted ascending, that's nums[n-1] + nums[n-2] + ... + nums[n-targetSize]
    // But we can only take from index onwards, so if n - index < targetSize, already handled.
    // Maximum sum from index with targetSize picks: take the largest targetSize elements from index to n-1, which are nums[n-1], nums[n-2], ..., nums[n-targetSize]
    // But these must all be >= index, so n-targetSize >= index => n - index >= targetSize (already checked).

    long maxPossibleSum = 0;
    for (int i = 0; i < targetSize; i++) {
        maxPossibleSum += nums[n - 1 - i];
    }
    if (maxPossibleSum < targetSum - currentSum) {
        return false;
    }

    // Minimum possible sum: take the smallest targetSize elements from index to n-1
    long minPossibleSum = 0;
    for (int i = 0; i < targetSize; i++) {
        minPossibleSum += nums[index + i];
    }
    if (minPossibleSum > targetSum - currentSum) {
        return false;
    }

    // Choose current element
    if (dfs(nums, index + 1, targetSize - 1, targetSum, currentSum + nums[index])) {
        return true;
    }
    // Skip current element
    if (dfs(nums, index + 1, targetSize, targetSum, currentSum)) {
        return true;
    }

    return false;
}
