public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k > n) {
        return false;
    }
    long total = 1L << k;
    long[] seen = new long[(int) total];
    int mask = (int) total - 1;
    long val = 0;

    for (int i = 0; i < n; i++) {
        val = ((val << 1) | (s.charAt(i) - '0')) & mask;
        if (i >= k - 1) {
            if (seen[(int) val] == 0) {
                seen[(int) val] = 1;
            }
        }
    }

    for (int i = 0; i < (int) total; i++) {
        if (seen[i] == 0) {
            return false;
        }
    }
    return true;
}
