public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    List<Integer> fibs = new ArrayList<>();
    int a = 1, b = 1;
    fibs.add(a);
    fibs.add(b);
    while (true) {
        int c = a + b;
        if (c > k) break;
        fibs.add(c);
        a = b;
        b = c;
    }

    int count = 0;
    // Greedy: pick the largest Fibonacci number <= k repeatedly
    int idx = fibs.size() - 1;
    while (k > 0) {
        while (idx >= 0 && fibs.get(idx) > k) {
            idx--;
        }
        k -= fibs.get(idx);
        count++;
    }

    return count;
}
