public String getSmallestString(int n, int k) {
    char[] result = new char[n];
    // Start with all 'a's
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    k -= n;
    // Now we need to distribute k additional value among the characters
    // To make it lexicographically smallest, we should put as much as possible at the end
    for (int i = n - 1; i >= 0 && k > 0; i--) {
        int add = Math.min(25, k); // max we can add to a char is 25 (from 'a' to 'z')
        result[i] = (char) (result[i] + add);
        k -= add;
    }
    return new String(result);
}
