public String getSmallestString(int n, int k) {
    // Allocate minimum 1 to each position first
    int remaining = k - n;
    char[] chars = new char[n];
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }
    // Distribute the remaining value from the end to keep the start as small as possible
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(remaining, 25); // max extra per character is 25 (z - a)
        chars[i] = (char) (chars[i] + add);
        remaining -= add;
    }
    return new String(chars);
}
