public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (high < low) {
        return result;
    }
    // Handle the case where 0 is in the range
    if (low <= 0 && high >= 0) {
        result.add(0);
    }
    // BFS to generate stepping numbers
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        queue.offer(i);
    }
    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num > high) {
            continue;
        }
        if (num >= low && num <= high && num > 0) {
            result.add(num);
        }
        int lastDigit = num % 10;
        int newNum;
        if (lastDigit > 0) {
            newNum = num * 10 + (lastDigit - 1);
            if (newNum <= high) {
                queue.offer(newNum);
            }
        }
        if (lastDigit < 9) {
            newNum = num * 10 + (lastDigit + 1);
            if (newNum <= high) {
                queue.offer(newNum);
            }
        }
    }
    Collections.sort(result);
    return result;
}
