    List<Integer> result = new ArrayList<>();
    if (low <= 0 && high >= 0) {
        result.add(0);
    }
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 1; i <= 9; i++) {
        if (i >= low && i <= high) {
            result.add(i);
        }
        queue.offer(i);
    }
    while (!queue.isEmpty()) {
        int current = queue.poll();
        if (current > high) {
            continue;
        }
        int lastDigit = current % 10;
        // Try lastDigit - 1
        if (lastDigit - 1 >= 0) {
            int next = current * 10 + (lastDigit - 1);
            if (next <= high) {
                queue.offer(next);
                if (next >= low) {
                    result.add(next);
                }
            }
        }
        // Try lastDigit + 1
        if (lastDigit + 1 <= 9) {
            int next = current * 10 + (lastDigit + 1);
            if (next <= high) {
                queue.offer(next);
                if (next >= low) {
                    result.add(next);
                }
            }
        }
    }
    Collections.sort(result);
    return result;
}
