public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int max = 0;

    // dp[i][j] = {horizontal, vertical, diagonal, anti-diagonal}
    int[][][] dp = new int[m][n][4];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 0) {
                dp[i][j][0] = 0;
                dp[i][j][1] = 0;
                dp[i][j][2] = 0;
                dp[i][j][3] = 0;
            } else {
                // Horizontal: from left
                if (j > 0) {
                    dp[i][j][0] = dp[i][j - 1][0] + 1;
                } else {
                    dp[i][j][0] = 1;
                }

                // Vertical: from above
                if (i > 0) {
                    dp[i][j][1] = dp[i - 1][j][1] + 1;
                } else {
                    dp[i][j][1] = 1;
                }

                // Diagonal: from top-left
                if (i > 0 && j > 0) {
                    dp[i][j][2] = dp[i - 1][j - 1][2] + 1;
                } else {
                    dp[i][j][2] = 1;
                }

                // Anti-diagonal: from top-right
                if (i > 0 && j < n - 1) {
                    dp[i][j][3] = dp[i - 1][j + 1][3] + 1;
                } else {
                    dp[i][j][3] = 1;
                }

                for (int k = 0; k < 4; k++) {
                    if (dp[i][j][k] > max) {
                        max = dp[i][j][k];
                    }
                }
            }
        }
    }

    return max;
}
