public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;

    // dp[i][j][dir]: length of the line ending at (i, j) in direction dir
    // dir 0: horizontal (left)
    // dir 1: vertical (up)
    // dir 2: diagonal (top-left)
    // dir 3: anti-diagonal (top-right)
    int[][][] dp = new int[m][n][4];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 0) {
                continue;
            }
            // Horizontal: check left
            dp[i][j][0] = 1;
            if (j > 0) {
                dp[i][j][0] = dp[i][j - 1][0] + 1;
            }

            // Vertical: check up
            dp[i][j][1] = 1;
            if (i > 0) {
                dp[i][j][1] = dp[i - 1][j][1] + 1;
            }

            // Diagonal: check top-left
            dp[i][j][2] = 1;
            if (i > 0 && j > 0) {
                dp[i][j][2] = dp[i - 1][j - 1][2] + 1;
            }

            // Anti-diagonal: check top-right
            dp[i][j][3] = 1;
            if (i > 0 && j < n - 1) {
                dp[i][j][3] = dp[i - 1][j + 1][3] + 1;
            }

            for (int dir = 0; dir < 4; dir++) {
                maxLen = Math.max(maxLen, dp[i][j][dir]);
            }
        }
    }

    return maxLen;
}
