public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Horizontal
                int h = 1;
                int jj = j + 1;
                while (jj < n && mat[i][jj] == 1) {
                    h++;
                    jj++;
                }
                maxLen = Math.max(maxLen, h);

                // Vertical
                int v = 1;
                int ii = i + 1;
                while (ii < m && mat[ii][j] == 1) {
                    v++;
                    ii++;
                }
                maxLen = Math.max(maxLen, v);

                // Diagonal (down-right)
                int d = 1;
                int ii2 = i + 1;
                int jj2 = j + 1;
                while (ii2 < m && jj2 < n && mat[ii2][jj2] == 1) {
                    d++;
                    ii2++;
                    jj2++;
                }
                maxLen = Math.max(maxLen, d);

                // Anti-diagonal (down-left)
                int ad = 1;
                int ii3 = i + 1;
                int jj3 = j - 1;
                while (ii3 < m && jj3 >= 0 && mat[ii3][jj3] == 1) {
                    ad++;
                    ii3++;
                    jj3--;
                }
                maxLen = Math.max(maxLen, ad);
            }
        }
    }
    return maxLen;
}
