public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    if (n == 1) return 1;

    // Count frequencies to handle duplicates
    // Use backtracking with visited set to avoid duplicates
    int[] freq = new int[n];
    boolean[] used = new boolean[n];
    int[] count = {1};
    int[] maxSquare = new int[n];
    int maxVal = 0;
    for (int v : A) {
        maxVal = Math.max(maxVal, v);
    }
    // Precompute squares up to (maxVal+maxVal)*2? Actually sum of two elements <= 2*maxVal
    // Let's precompute a set of perfect squares up to 2 * maxVal
    java.util.Set<Integer> squares = new java.util.HashSet<>();
    for (int i = 0; i * i <= 2 * maxVal; i++) {
        squares.add(i * i);
    }

    // Backtracking
    backtrack(A, 0, n - 1, used, squares, count);

    return count[0];
}

private static void backtrack(int[] A, int start, int end, boolean[] used, java.util.Set<Integer> squares, int[] count) {
    if (start >= end) {
        count[0]++;
        return;
    }

    // For the next position, try each unused element
    // To avoid duplicates, if two elements are the same, only pick the first one among consecutive duplicates that are unused
    Integer prevPicked = null;
    for (int i = 0; i < A.length; i++) {
        if (used[i]) continue;

        // Duplicate pruning: if the last picked element in this level is the same, skip
        if (prevPicked != null && prevPicked == A[i]) continue;

        // Check if the element is valid to place at position 'start'
        if (start == 0) {
            // First element, no constraint
            used[i] = true;
            backtrack(A, start + 1, end, used, squares, count);
            used[i] = false;
            prevPicked = A[i];
        } else {
            // Need to check if A[i] + A[start-1] is a perfect square
            int sum = A[i] + A[start - 1];
            if (squares.contains(sum)) {
                used[i] = true;
                backtrack(A, start + 1, end, used, squares, count);
                used[i] = false;
                prevPicked = A[i];
            } else {
                // If not square, we still need to update prevPicked for pruning later duplicates
                prevPicked = A[i];
            }
        }
    }
}
