public static int squarePermutations(int[] A) {
    if (A == null) {
        return 0;
    }
    int n = A.length;
    if (n == 0) {
        return 1;
    }

    // Precompute which pairs sum to a perfect square
    boolean[][] isSquarePair = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            if (sqrt * sqrt == sum || (sqrt + 1) * (sqrt + 1) == sum) {
                isSquarePair[i][j] = true;
            }
        }
    }

    // Use backtracking with memoization.
    // State: used mask (bitmask of which elements are used), and lastIndex
    // Since n can be up to 6 (CDO note: it's rare for the array to be more than 6),
    // bitmask approach is feasible.
    // memo[mask][lastIndex] = number of ways to complete the permutation starting from state (mask, lastIndex)
    // If mask == 0 and lastIndex == -1, we are at the start.

    // Alternative: use memoization with HashMap or 2D array.
    // mask: 0 to (1<<n)-1, lastIndex: 0 to n-1, plus a special case for start.
    // Let's use a DP where we build the permutation from the start.
    // dp[mask][lastIndex]: number of ways to form a valid partial sequence with elements indicated by mask, ending with element at index lastIndex.
    // We want the sum of dp[(1<<n)-1][i] for all i, where the full mask is used.

    // If n == 1, there's only one permutation, and it's trivially a square array (no adjacent pairs to check).
    if (n == 1) {
        return 1;
    }

    int fullMask = (1 << n) - 1;
    int[][] dp = new int[1 << n][n];

    // Initialize: sequences of length 1
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }

    // Transition: extend sequences
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            if (dp[mask][last] == 0) continue;
            // Try to append any unused element 'next'
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue; // already used
                if (!isSquarePair[last][next]) continue; // not a valid pair
                int newMask = mask | (1 << next);
                dp[newMask][next] += dp[mask][last];
            }
        }
    }

    int result = 0;
    for (int last = 0; last < n; last++) {
        result += dp[fullMask][last];
    }

    return result;
}
