private static void permute(int[] A, boolean[] used, int pos, int lastIdx, int[] result) {
    if (pos == A.length) {
        result[0]++;
        return;
    }

    for (int i = 0; i < A.length; i++) {
        if (used[i]) continue;

        // Skip duplicate values at the same position level to avoid counting identical permutations
        // Actually, we need to be careful: two permutations are different if any index differs.
        // But if we have duplicate values, swapping them at the same position gives same permutation.
        // So we should skip duplicates at the same recursion depth.
        if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;

        if (lastIdx != -1) {
            if (!isPerfectSquare(A[lastIdx] + A[i])) continue;
        }

        used[i] = true;
        permute(A, used, pos + 1, i, result);
        used[i] = false;
    }
}

