public static int findSmallestInteger(int n) {
    String s = String.valueOf(n);
    char[] chars = s.toCharArray();
    int len = chars.length;

    // Step 1: Find the rightmost digit that is smaller than the digit after it
    int i = len - 2;
    while (i >= 0 && chars[i] >= chars[i + 1]) {
        i--;
    }

    // If no such digit found, the number is the largest permutation
    if (i < 0) {
        return -1;
    }

    // Step 2: Find the smallest digit greater than chars[i] to the right of i
    int j = len - 1;
    while (chars[j] <= chars[i]) {
        j--;
    }

    // Step 3: Swap chars[i] and chars[j]
    char temp = chars[i];
    chars[i] = chars[j];
    chars[j] = temp;

    // Step 4: Reverse all digits after index i
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = chars[left];
        chars[left] = chars[right];
        chars[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer
    String result = new String(chars);
    return Integer.parseInt(result);
}
