private static void buildEven(char[] left, char[] right, int len, int pos, char[] buffer, List<String> result) {
    if (pos == len) {
        // Construct the full string: buffer[0..len-1] and then mirror in reverse
        char[] full = new char[len * 2];
        for (int i = 0; i < len; i++) {
            full[i] = buffer[i];
            full[len * 2 - 1 - i] = right[leftToRightIndex(left, buffer[i])];
        }
        result.add(new String(full));
        return;
    }
    for (int i = 0; i < left.length; i++) {
        buffer[pos] = left[i];
        buildEven(left, right, len, pos + 1, buffer, result);
    }
}

private static void buildOdd(char[] left, char[] right, char[] middle, int len, int pos, int n, char[] buffer, List<String> result) {
    if (pos == len) {
        // Add middle character
        for (int m = 0; m < middle.length; m++) {
            buffer[len] = middle[m];
            // Construct the full string
            char[] full = new char[n];
            for (int i = 0; i < len; i++) {
                full[i] = buffer[i];
                full[n - 1 - i] = right[leftToRightIndex(left, buffer[i])];
            }
            // Middle is already set at position len
            result.add(new String(full));
        }
        return;
    }
    for (int i = 0; i < left.length; i++) {
        buffer[pos] = left[i];
        buildOdd(left, right, middle, len, pos + 1, n, buffer, result);
    }
}

private static int leftToRightIndex(char[] left, char c) {
    for (int i = 0; i < left.length; i++) {
        if (left[i] == c) {
            return i;
        }
    }
    return -1;
