public static boolean isBoomerang(int[][] points) {
    // A boomerang is defined as a set of three distinct points such that no three points are collinear.
    // In other words, the points do not lie on the same straight line.
    // We can check collinearity using the cross product (or area of triangle).
    // Given three points A(x1, y1), B(x2, y2), C(x3, y3), they are collinear if:
    // (x2 - x1)*(y3 - y1) == (x3 - x1)*(y2 - y1)
    // If they are NOT collinear, it's a boomerang.

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check if points are collinear
    int cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);

    // If cross product is zero, points are collinear, not a boomerang
    return cross != 0;
}
