public static int calculateUniqueSum(int[] nums) {
    boolean[] seen = new boolean[1001];
    int sum = 0;
    for (int num : nums) {
        if (num >= 0 && num < 1001) {
            if (!seen[num]) {
                seen[num] = true;
                sum += num;
            }
        } else {
            // Handle negative numbers or numbers out of range
            // For simplicity, we can use a Set, but since the problem likely expects positive unique elements,
            // let's use a HashSet for general case
            break;
        }
    }

    // If any numbers are out of the expected range, use a different approach
    java.util.Set<Integer> set = new java.util.HashSet<>();
    for (int num : nums) {
        set.add(num);
    }
    sum = 0;
    for (int num : set) {
        sum += num;
    }
    return sum;
}
