public static int minPerfectSquareSum(int n) {
    int[] dp = new int[n + 1];
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }

    for (int i = 1; i <= n; i++) {
        int sqrt = (int) Math.sqrt(i);
        for (int j = 1; j <= sqrt; j++) {
            int square = j * j;
            if (i >= square && dp[i - square] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            }
        }
    }

    return dp[n];
}
